timer_task.text:
// update_last
/// 定时查询并且更新上次处理某些事务的时间点
/// 还没有上次更新记录, 以当前时间作为初次记录，但是不处理更新逻辑
[%living%+1 && %[%{last_update_year_%up_uid%}%+0]%==0]>triggerEvent(UPDATE_LAST_TIME)
/// 跨年了，那肯定也跨月了，跨天了
[%living%+1 && %[%{last_update_year_%up_uid%}%+0]%!=0 && %[%{last_update_year_%up_uid%}%+0]% != %time_year%]>triggerEvent(UPDATE_YEAR)\n\
	>triggerEvent(UPDATE_MONTH)\n\
	>triggerEvent(UPDATE_DAY)\n\
	>triggerEvent(UPDATE_LAST_TIME)
/// 没跨年 跨月了，那肯定也跨天了
[%living%+1 && %[%{last_update_year_%up_uid%}%+0]%!=0 && %[%{last_update_year_%up_uid%}%+0]% == %time_year% && %[%{last_update_month_%up_uid%}%+0]% != %time_month%]>triggerEvent(UPDATE_MONTH)\n\
	>triggerEvent(UPDATE_DAY)\n\
	>triggerEvent(UPDATE_LAST_TIME)
/// 没跨年，没跨月，只跨天了
[%living%+1 && %[%{last_update_year_%up_uid%}%+0]%!=0 && %[%{last_update_year_%up_uid%}%+0]% == %time_year% && %[%{last_update_month_%up_uid%}%+0]% == %time_month% && %[%{last_update_day_%up_uid%}%+0]% != %time_day%]>triggerEvent(UPDATE_DAY)\n\
	>triggerEvent(UPDATE_LAST_TIME)
